1	import type * as Tone from 'tone';
2	import type { Rack } from './rack';
3	import type { Score } from '../core/music/score';
4	
5	type Transport = ReturnType<typeof Tone.getTransport>;
6	
7	/**
8	 * Schedule every note and pad chord of a score on a transport (live or offline).
9	 * Audio is always triggered with the `time` the transport passes in — never from timers.
10	 */
11	export function scheduleScore(transport: Transport, rack: Rack, score: Score, from = 0): void {
12	  for (const note of score.notes) {
13	    if (note.time < from - 1e-6) continue;
14	    transport.schedule((time) => rack.play(note, time), note.time);
15	  }
16	  for (const chord of score.chords) {
17	    if (chord.time < from - 1e-6) continue;
18	    transport.schedule((time) => rack.playChord(chord, time), chord.time);
19	  }
20	}
