1	// The instrument rack. ONE factory serves both live playback and Tone.Offline export, so the
2	// downloaded file sounds exactly like what the listener heard. Every node is created with the
3	// current Tone context (inside Tone.Offline that is the offline context).
4	
5	import * as Tone from 'tone';
6	import { createRng } from '../core/random';
7	import { getMood, type AmbienceId, type LeadId, type MoodId } from '../core/music/moods';
8	import { degreeToMidi, midiToFreq, SCALES } from '../core/music/theory';
9	import type { ScoreChord, ScoreNote } from '../core/music/score';
10	
11	type Transport = ReturnType<typeof Tone.getTransport>;
12	
13	export interface RackOptions {
14	  bpm: number;
15	  ambience: Partial<Record<AmbienceId, number>>;
16	  /** include ambience at all (export toggle) */
17	  withAmbience: boolean;
18	  seed: string;
19	}
20	
21	export interface Rack {
22	  readonly moodId: MoodId;
23	  readonly ready: Promise<void>;
24	  readonly output: Tone.Gain;
25	  play(note: ScoreNote, time: number, durationOverride?: number): void;
26	  playChord(chord: ScoreChord, time: number, durationOverride?: number): void;
27	  /** soften every sounding voice (used before seeking and on stop) */
28	  releaseAll(time?: number): void;
29	  setAmbience(layer: AmbienceId, level: number, ramp?: number): void;
30	  /** schedule the occasional ambience events (birds, chimes, crackles) on a transport */
31	  scheduleAmbience(transport: Transport, from?: number): void;
32	  setTempo(bpm: number): void;
33	  dispose(): void;
34	}
35	
36	const db = (x: number) => Tone.dbToGain(x);
37	const hz = (midi: number) => midiToFreq(midi);
38	
39	interface Voice {
40	  trigger(midi: number, dur: number, time: number, vel: number): void;
41	  release(time: number): void;
42	  output: Tone.ToneAudioNode;
43	  dispose(): void;
44	}
45	
46	function polyVoice(synth: Tone.PolySynth): Voice {
47	  return {
48	    trigger: (m, d, t, v) => synth.triggerAttackRelease(hz(m), d, t, v),
49	    release: (t) => synth.releaseAll(t),
50	    output: synth,
51	    dispose: () => synth.dispose(),
52	  };
53	}
54	
55	/** a small pool of Karplus–Strong plucks (PluckSynth is monophonic): a feedback loop, so even the sound is recursive */
56	function pluckVoice(opts: { dampening: number; resonance: number; attackNoise: number; size?: number }): Voice {
57	  const out = new Tone.Gain(1);
58	  const pool = Array.from({ length: opts.size ?? 6 }, () => {
59	    const synth = new Tone.PluckSynth({ attackNoise: opts.attackNoise, dampening: opts.dampening, resonance: opts.resonance, release: 1.2 });
60	    const gain = new Tone.Gain(0.5);
61	    synth.connect(gain);
62	    gain.connect(out);
63	    return { synth, gain };
64	  });
65	  let i = 0;
66	  return {
67	    trigger: (m, d, t, v) => {
68	      const p = pool[i++ % pool.length];
69	      p.gain.gain.setValueAtTime(v, t);
70	      p.synth.triggerAttackRelease(hz(m), Math.max(0.2, d), t);
71	    },
72	    release: (t) => pool.forEach((p) => p.gain.gain.setTargetAtTime(0, t, 0.08)),
73	    output: out,
74	    dispose: () => {
75	      pool.forEach((p) => {
76	        p.synth.dispose();
77	        p.gain.dispose();
78	      });
79	      out.dispose();
80	    },
81	  };
82	}
83	
84	function leadVoice(lead: LeadId): Voice {
85	  switch (lead) {
86	    case 'epiano':
87	      return polyVoice(
88	        new Tone.PolySynth({
89	          voice: Tone.FMSynth,
90	          maxPolyphony: 16,
91	          options: {
92	            harmonicity: 3,
93	            modulationIndex: 2.2,
94	            oscillator: { type: 'sine' },
95	            modulation: { type: 'sine' },
96	            envelope: { attack: 0.012, decay: 1.6, sustain: 0.15, release: 2.4 },
97	            modulationEnvelope: { attack: 0.01, decay: 0.6, sustain: 0.1, release: 1.2 },
98	          },
99	        }),
100	      );
101	    case 'kalimba':
102	      return polyVoice(
103	        new Tone.PolySynth({
104	          voice: Tone.FMSynth,
105	          maxPolyphony: 16,
106	          options: {
107	            harmonicity: 8,
108	            modulationIndex: 1.6,
109	            oscillator: { type: 'sine' },
110	            modulation: { type: 'sine' },
111	            envelope: { attack: 0.004, decay: 1.1, sustain: 0, release: 1.4 },
112	            modulationEnvelope: { attack: 0.002, decay: 0.25, sustain: 0, release: 0.4 },
113	          },
114	        }),
115	      );
116	    case 'glass':
117	      return polyVoice(
118	        new Tone.PolySynth({
119	          voice: Tone.FMSynth,
120	          maxPolyphony: 16,
121	          options: {
122	            harmonicity: 3.5,
123	            modulationIndex: 3,
124	            oscillator: { type: 'sine' },
125	            modulation: { type: 'sine' },
126	            envelope: { attack: 0.02, decay: 2.8, sustain: 0.05, release: 3.2 },
127	            modulationEnvelope: { attack: 0.01, decay: 0.9, sustain: 0.05, release: 1.5 },
128	          },
129	        }),
130	      );
131	    case 'harp':
132	      return pluckVoice({ attackNoise: 0.6, dampening: 3200, resonance: 0.93 });
133	    case 'koto':
134	      return pluckVoice({ attackNoise: 0.9, dampening: 2600, resonance: 0.95 });
135	  }
136	}
