138	export function createRack(moodId: MoodId, opts: RackOptions): Rack {
139	  const mood = getMood(moodId);
140	  const context = Tone.getContext(); // live or offline; every node below binds to it
141	  const nodes: Array<{ dispose(): unknown }> = [];
142	  const keep = <T extends { dispose(): unknown }>(n: T): T => {
143	    nodes.push(n);
144	    return n;
145	  };
146	
147	  // ── master chain: sum → EQ → compressor → makeup → limiter(−1 dB) → output
148	  const sum = keep(new Tone.Gain(1));
149	  const eq = keep(new Tone.EQ3({ low: 0, mid: -1, high: -3 }));
150	  const comp = keep(new Tone.Compressor({ threshold: -20, ratio: 2.5, attack: 0.03, release: 0.3 }));
151	  // makeup gain into the limiter: measured raw mix ≈ −25 dB RMS, so +6 dB lands live playback near −19
152	  const makeup = keep(new Tone.Gain(db(6)));
153	  const limiter = keep(new Tone.Limiter(-1));
154	  const output = keep(new Tone.Gain(1));
155	  sum.chain(eq, comp, makeup, limiter, output);
156	
157	  // ── sends: one long reverb (low-cut return) and a dotted-eighth delay
158	  const reverb = keep(new Tone.Reverb({ decay: 7, preDelay: 0.04, wet: 1 }));
159	  const reverbLowCut = keep(new Tone.Filter(220, 'highpass'));
160	  const reverbIn = keep(new Tone.Gain(1));
161	  reverbIn.chain(reverb, reverbLowCut, sum);
162	  const delay = keep(new Tone.FeedbackDelay({ delayTime: (60 / opts.bpm) * 0.75, feedback: 0.3, wet: 1 }));
163	  const delayTone = keep(new Tone.Filter(2600, 'lowpass'));
164	  const delayIn = keep(new Tone.Gain(1));
165	  delayIn.chain(delay, delayTone);
166	  delayTone.connect(sum);
167	  delayTone.connect(reverbIn);
168	
169	  const send = (node: Tone.ToneAudioNode, reverbAmt: number, delayAmt = 0) => {
170	    const r = keep(new Tone.Gain(reverbAmt));
171	    node.connect(r);
172	    r.connect(reverbIn);
173	    if (delayAmt > 0) {
174	      const d = keep(new Tone.Gain(delayAmt));
175	      node.connect(d);
176	      d.connect(delayIn);
177	    }
178	  };
179	
180	  // ── pad: fat triangles, slow filter LFO, chorus
181	  const padSynth = keep(
182	    new Tone.PolySynth({
183	      voice: Tone.Synth,
184	      maxPolyphony: 14,
185	      options: {
186	        oscillator: { type: 'fattriangle', count: 2, spread: 16 },
187	        envelope: { attack: 2.5, decay: 1, sustain: 0.8, release: 6 },
188	      },
189	    }),
190	  );
191	  const padHp = keep(new Tone.Filter(150, 'highpass'));
192	  const padLp = keep(new Tone.Filter({ frequency: 1200, type: 'lowpass', rolloff: -24 }));
193	  const padLfo = keep(new Tone.LFO({ frequency: 0.05, min: 700, max: 1600 }));
194	  padLfo.connect(padLp.frequency);
195	  padLfo.start();
196	  const chorus = keep(new Tone.Chorus({ frequency: 0.3, delayTime: 3.5, depth: 0.4, wet: 0.5 }));
197	  chorus.start();
198	  const padOut = keep(new Tone.Gain(db(-18)));
199	  padSynth.chain(padHp, padLp, chorus, padOut, sum);
200	  send(padOut, 0.45);
201	  const pad = polyVoice(padSynth);
202	
203	  // ── drone: root + fifth, slow swell and a gentle amplitude LFO
204	  const droneSynth = keep(
205	    new Tone.PolySynth({
206	      voice: Tone.Synth,
207	      maxPolyphony: 6,
208	      options: { oscillator: { type: mood.id === 'temple' ? 'fatsine' : 'sine', count: 2, spread: 6 } as never, envelope: { attack: 6, decay: 0, sustain: 1, release: 8 } },
209	    }),
210	  );
211	  const droneTrem = keep(new Tone.Gain(1));
212	  const droneLfo = keep(new Tone.LFO({ frequency: 0.07, min: 0.75, max: 1 }));
213	  droneLfo.connect(droneTrem.gain);
214	  droneLfo.start();
215	  const droneOut = keep(new Tone.Gain(db(-22)));
216	  droneSynth.chain(droneTrem, droneOut, sum);
217	  send(droneOut, 0.25);
218	  const drone = polyVoice(droneSynth);
219	
220	  // ── bass: soft sine on chord roots
221	  const bassSynth = keep(
222	    new Tone.PolySynth({ voice: Tone.Synth, maxPolyphony: 4, options: { oscillator: { type: 'sine' }, envelope: { attack: 1.2, decay: 0.5, sustain: 0.8, release: 4 } } }),
223	  );
224	  const bassLp = keep(new Tone.Filter(320, 'lowpass'));
225	  const bassOut = keep(new Tone.Gain(db(-21)));
226	  bassSynth.chain(bassLp, bassOut, sum);
227	  const bass = polyVoice(bassSynth);
228	
229	  // ── lead (per mood), shared by ornaments; panned per note
230	  const lead = leadVoice(mood.lead);
231	  keep(lead);
232	  const leadHp = keep(new Tone.Filter(180, 'highpass'));
233	  const leadLp = keep(new Tone.Filter(mood.lead === 'glass' ? 3800 : 4500, 'lowpass'));
234	  const leadPan = keep(new Tone.Panner(0));
235	  const leadLevel = mood.lead === 'harp' || mood.lead === 'koto' ? -9 : mood.lead === 'glass' ? -17 : -14;
236	  const leadOut = keep(new Tone.Gain(db(leadLevel)));
237	  lead.output.chain(leadHp, leadLp, leadPan, leadOut, sum);
238	  send(leadOut, mood.lead === 'glass' ? 0.6 : 0.4, 0.2);
239	
240	  // ── bells: FM bell, high-passed, heavy reverb
241	  const bellSynth = keep(
242	    new Tone.PolySynth({
243	      voice: Tone.FMSynth,
244	      maxPolyphony: 24,
245	      options: {
246	        harmonicity: 5.07,
247	        modulationIndex: 6,
248	        oscillator: { type: 'sine' },
249	        modulation: { type: 'sine' },
250	        envelope: { attack: 0.004, decay: 3.5, sustain: 0, release: 3 },
251	        modulationEnvelope: { attack: 0.002, decay: 0.7, sustain: 0.15, release: 2 },
252	      },
253	    }),
254	  );
255	  const bellHp = keep(new Tone.Filter(400, 'highpass'));
256	  const bellLp = keep(new Tone.Filter(6000, 'lowpass'));
257	  const bellPan = keep(new Tone.Panner(0));
258	  const bellOut = keep(new Tone.Gain(db(-22)));
259	  bellSynth.chain(bellHp, bellLp, bellPan, bellOut, sum);
260	  send(bellOut, 0.75, 0.22);
261	  const bell = polyVoice(bellSynth);
262	
263	  // ── ambience: procedural layers, created on demand
264	  const ambBus = keep(new Tone.Gain(opts.withAmbience ? 1 : 0));
265	  ambBus.connect(sum);
266	  const layers = new Map<AmbienceId, { gain: Tone.Gain; max: number; parts: Array<{ dispose(): unknown }>; sources: Array<Tone.Noise | Tone.Oscillator> }>();
267	  const levels: Partial<Record<AmbienceId, number>> = { ...opts.ambience };
268	
269	  function buildLayer(id: AmbienceId) {
270	    const parts: Array<{ dispose(): unknown }> = [];
271	    const sources: Array<Tone.Noise | Tone.Oscillator> = [];
272	    const p = <T extends { dispose(): unknown }>(n: T) => {
273	      parts.push(n);
274	      return n;
275	    };
276	    const gain = p(new Tone.Gain(0));
277	    gain.connect(ambBus);
278	    let max = db(-28);
279	    const lfo = (frequency: number, min: number, max: number, target: Tone.Param<'frequency'> | Tone.Param<'gain'> | Tone.Signal<'frequency'>, type: 'sine' | 'square' = 'sine') => {
280	      const l = p(new Tone.LFO({ frequency, min, max, type }));
281	      l.connect(target as never);
282	      l.start();
283	      return l;
284	    };
285	    switch (id) {
286	      case 'rain': {
287	        const n = p(new Tone.Noise('pink'));
288	        const hp = p(new Tone.Filter(400, 'highpass'));
289	        const lp = p(new Tone.Filter(3500, 'lowpass'));
290	        n.chain(hp, lp, gain);
291	        const patter = p(new Tone.Noise('white'));
292	        const php = p(new Tone.Filter(5200, 'highpass'));
293	        const pg = p(new Tone.Gain(0.25));
294	        lfo(0.23, 0.12, 0.35, pg.gain);
295	        patter.chain(php, pg, gain);
296	        sources.push(n, patter);
297	        max = db(-27);
298	        break;
299	      }
300	      case 'ocean': {
301	        const n = p(new Tone.Noise('brown'));
302	        const af = p(new Tone.AutoFilter({ frequency: 0.08, baseFrequency: 200, octaves: 3, wet: 1 }));
303	        af.start();
304	        const swell = p(new Tone.Gain(0.6));
305	        lfo(1 / 12, 0.25, 1, swell.gain);
306	        n.chain(af, swell, gain);
307	        sources.push(n);
308	        max = db(-22);
309	        break;
310	      }
311	      case 'wind': {
312	        const n = p(new Tone.Noise('pink'));
313	        const bp = p(new Tone.Filter({ frequency: 600, type: 'bandpass', Q: 1.4 }));
314	        lfo(0.05, 250, 1100, bp.frequency);
315	        const g = p(new Tone.Gain(0.7));
316	        lfo(0.09, 0.35, 1, g.gain);
317	        n.chain(bp, g, gain);
318	        sources.push(n);
319	        max = db(-26);
320	        break;
321	      }
322	      case 'stream': {
323	        const n = p(new Tone.Noise('white'));
324	        const bp = p(new Tone.Filter({ frequency: 2000, type: 'bandpass', Q: 0.8 }));
325	        lfo(3.3, 1500, 3000, bp.frequency);
326	        const lp = p(new Tone.Filter(4500, 'lowpass'));
327	        n.chain(bp, lp, gain);
328	        sources.push(n);
329	        max = db(-31);
330	        break;
331	      }
332	      case 'crickets': {
333	        const mk = (f: number, trill: number, pulse: number, pan: number) => {
334	          const o = p(new Tone.Oscillator(f, 'sine'));
335	          const t = p(new Tone.Gain(0));
336	          lfo(trill, 0, 1, t.gain, 'square');
337	          const pg = p(new Tone.Gain(0));
338	          lfo(pulse, 0, 1, pg.gain, 'square');
339	          const pn = p(new Tone.Panner(pan));
340	          o.chain(t, pg, pn, gain);
341	          sources.push(o);
342	        };
343	        mk(4300, 28, 0.62, -0.5);
344	        mk(4720, 31, 0.47, 0.45);
345	        max = db(-36);
346	        break;
347	      }
348	      case 'fire': {
349	        const n = p(new Tone.Noise('brown'));
350	        const lp = p(new Tone.Filter(480, 'lowpass'));
351	        const g = p(new Tone.Gain(0.8));
352	        lfo(0.31, 0.6, 1, g.gain);
353	        n.chain(lp, g, gain);
354	        sources.push(n);
355	        max = db(-28);
356	        break;
357	      }
358	      case 'birds':
359	      case 'chimes':
360	        max = db(-26);
361	        break;
362	    }
363	    return { gain, max, parts, sources };
364	  }
365	
366	  function ensureLayer(id: AmbienceId) {
367	    let l = layers.get(id);
368	    if (!l) {
369	      l = buildLayer(id);
370	      layers.set(id, l);
371	      for (const s of l.sources) s.start();
372	    }
373	    return l;
374	  }
375	  function setAmbience(id: AmbienceId, level: number, ramp = 1.5) {
376	    levels[id] = level;
377	    const ev = eventGains[id];
378	    if (ev) ev.gain.gain.rampTo(level * level * ev.max * 1.6, ramp);
379	    if (id === 'birds' || id === 'chimes') return;
380	    if (level <= 0 && !layers.has(id)) return;
381	    const l = ensureLayer(id);
382	    l.gain.gain.rampTo(level * level * l.max * 1.6, ramp);
383	  }
384	
385	  // occasional ambience events (created up front: callbacks may run while another context is global)
386	  const birdSynth = keep(new Tone.Synth({ oscillator: { type: 'sine' }, envelope: { attack: 0.01, decay: 0.05, sustain: 0.3, release: 0.05 } }));
387	  const birdHp = keep(new Tone.Filter(1800, 'highpass'));
388	  const birdPan = keep(new Tone.Panner(0));
389	  const birdGain = keep(new Tone.Gain(0));
390	  birdSynth.chain(birdHp, birdPan, birdGain, ambBus);
391	  send(birdPan, 0.5);
392	  const chimeSynth = keep(
393	    new Tone.PolySynth({
394	      voice: Tone.FMSynth,
395	      maxPolyphony: 8,
396	      options: { harmonicity: 5.07, modulationIndex: 4, envelope: { attack: 0.004, decay: 4, sustain: 0, release: 4 }, modulationEnvelope: { attack: 0.002, decay: 0.5, sustain: 0, release: 1 } },
397	    }),
398	  );
399	  const chimeHp = keep(new Tone.Filter(700, 'highpass'));
400	  const chimeGain = keep(new Tone.Gain(0));
401	  chimeSynth.chain(chimeHp, chimeGain, ambBus);
402	  send(chimeGain, 0.9);
403	  const crackle = keep(new Tone.NoiseSynth({ noise: { type: 'white' }, envelope: { attack: 0.001, decay: 0.025, sustain: 0, release: 0.01 } }));
404	  const crackleHp = keep(new Tone.Filter(1900, 'highpass'));
405	  const crackleGain = keep(new Tone.Gain(0));
406	  crackle.chain(crackleHp, crackleGain, ambBus);
407	  const eventGains: Partial<Record<AmbienceId, { gain: Tone.Gain; max: number }>> = {
408	    birds: { gain: birdGain, max: db(-24) },
409	    chimes: { gain: chimeGain, max: db(-22) },
410	    fire: { gain: crackleGain, max: db(-30) },
411	  };
412	  if (opts.withAmbience) for (const [id, v] of Object.entries(levels)) if ((v ?? 0) > 0) setAmbience(id as AmbienceId, v ?? 0, 3);
413	
414	  function scheduleAmbience(transport: Transport, from = 0) {
415	    if (!opts.withAmbience) return;
416	    const rng = createRng(`ambience:${opts.seed}:${from.toFixed(2)}`);
417	    // birds: short rising chirps in little groups
418	    transport.scheduleRepeat(
419	      (time) => {
420	        const lvl = levels.birds ?? 0;
421	        if (lvl <= 0 || !rng.chance(0.4)) return;
422	        const count = rng.int(2, 4);
423	        const base = rng.range(2600, 3900);
424	        birdPan.pan.setValueAtTime(rng.range(-0.7, 0.7), time);
425	        for (let i = 0; i < count; i++) {
426	          const t = time + i * rng.range(0.11, 0.2);
427	          const f0 = base * rng.range(0.9, 1.1);
428	          birdSynth.triggerAttackRelease(f0, 0.07, t, 0.35 + rng() * 0.3);
429	          birdSynth.frequency.setValueAtTime(f0, t);
430	          birdSynth.frequency.exponentialRampToValueAtTime(f0 * rng.range(1.15, 1.45), t + 0.07);
431	        }
432	      },
433	      2.7,
434	      from,
435	    );
436	    // chimes: distant bells on pentatonic scale notes
437	    transport.scheduleRepeat(
438	      (time) => {
439	        const lvl = levels.chimes ?? 0;
440	        if (lvl <= 0 || !rng.chance(0.45)) return;
441	        const scale = SCALES[mood.scale];
442	        const m = degreeToMidi(rng.int(10, 15), scale, 60 + mood.keyPc - 12);
443	        chimeSynth.triggerAttackRelease(hz(m), 2, time, 0.25 + rng() * 0.2);
444	      },
445	      3.9,
446	      from + 1.3,
447	    );
448	    // fire: little crackles
449	    transport.scheduleRepeat(
450	      (time) => {
451	        const lvl = levels.fire ?? 0;
452	        if (lvl <= 0 || !rng.chance(0.18)) return;
453	        crackle.triggerAttackRelease(0.02, time + rng.range(0, 0.1), 0.3 + rng() * 0.6);
454	      },
455	      0.13,
456	      from + 0.5,
457	    );
458	  }
459	
460	  return {
461	    moodId,
462	    ready: reverb.ready,
463	    output,
464	    play(note, time, durationOverride) {
465	      const dur = durationOverride ?? note.duration;
466	      switch (note.voice) {
467	        case 'lead':
468	        case 'ornament':
469	          leadPan.pan.setTargetAtTime(note.pan, time, 0.05);
470	          lead.trigger(note.midi, dur, time, note.voice === 'ornament' ? note.velocity * 0.75 : note.velocity);
471	          break;
472	        case 'bell':
473	          bellPan.pan.setTargetAtTime(note.pan, time, 0.05);
474	          bell.trigger(note.midi, dur, time, note.velocity);
475	          break;
476	        case 'drone':
477	          drone.trigger(note.midi, dur, time, note.velocity);
478	          break;
479	        case 'bass':
480	          bass.trigger(note.midi, dur, time, note.velocity);
481	          break;
482	        case 'pad':
483	          pad.trigger(note.midi, dur, time, note.velocity);
484	          break;
485	      }
486	    },
487	    playChord(chord, time, durationOverride) {
488	      const dur = durationOverride ?? chord.duration;
489	      padSynth.triggerAttackRelease(chord.midis.map(hz), dur, time, 0.55);
490	    },
491	    releaseAll(time = context.now()) {
492	      for (const v of [pad, drone, bass, lead, bell]) v.release(time);
493	    },
494	    setAmbience,
495	    scheduleAmbience,
496	    setTempo(bpm) {
497	      delay.delayTime.rampTo((60 / bpm) * 0.75, 0.5);
498	    },
499	    dispose() {
500	      for (const l of layers.values()) {
501	        for (const s of l.sources) s.stop();
502	        l.parts.forEach((x) => x.dispose());
503	      }
504	      layers.clear();
505	      for (const n of nodes.reverse()) n.dispose();
506	      nodes.length = 0;
507	    },
508	  };
509	}
