1	// Live playback. Schedules a Score on the Tone transport through the shared rack, and exposes a
2	// calm transport API: every start, stop, seek and change is ramped so nothing clicks or startles.
3	
4	import * as Tone from 'tone';
5	import { createRack, type Rack } from './rack';
6	import { scheduleScore } from './schedule';
7	import type { AmbienceId, MoodId } from '../core/music/moods';
8	import { totalLength, type Score } from '../core/music/score';
9	
10	export type EngineState = 'idle' | 'playing' | 'paused';
11	
12	export interface EngineSettings {
13	  volume: number; // 0..1
14	  muted: boolean;
15	  mono: boolean;
16	  ambience: Partial<Record<AmbienceId, number>>;
17	}
18	
19	const FADE_IN = 1.6;
20	const FADE_OUT = 0.7;
21	const DIP = 1.1;
22	
23	type Ctx = ReturnType<typeof Tone.getContext>;
24	type Transport = ReturnType<typeof Tone.getTransport>;
25	
26	export class AudioEngine {
27	  // captured once: Tone.Offline swaps the global context while an export is being set up
28	  private ctx: Ctx | null = null;
29	  private transport: Transport | null = null;
30	  private rack: Rack | null = null;
31	  private score: Score | null = null;
32	  private master: Tone.Gain | null = null;
33	  private fade: Tone.Gain | null = null;
34	  private widener: Tone.StereoWidener | null = null;
35	  private recorderTap: Tone.Gain | null = null;
36	  private settings: EngineSettings = { volume: 0.8, muted: false, mono: false, ambience: {} };
37	  private busy: Promise<void> = Promise.resolve();
38	  state: EngineState = 'idle';
39	  unlocked = false;
40	
41	  /** must run inside a user gesture (the Begin button) */
42	  async unlock(): Promise<void> {
43	    if (this.unlocked) return;
44	    // Tone.start() resumes the AudioContext. Some browsers (background tabs, some phones) keep it
45	    // suspended until a later gesture, so never wait on it forever: retry on the next tap instead.
46	    await Promise.race([Tone.start(), wait(1200)]);
47	    if (Tone.getContext().state !== 'running') {
48	      const retry = () => {
49	        void Tone.start();
50	        if (Tone.getContext().state === 'running') {
51	          window.removeEventListener('pointerdown', retry);
52	          window.removeEventListener('keydown', retry);
53	        }
54	      };
55	      window.addEventListener('pointerdown', retry);
56	      window.addEventListener('keydown', retry);
57	    }
58	    const nav = navigator as Navigator & { audioSession?: { type: string } };
59	    try {
60	      if (nav.audioSession) nav.audioSession.type = 'playback'; // iOS: play even with the silent switch on
61	    } catch {
62	      /* not supported */
63	    }
64	    const ctx = Tone.getContext();
65	    ctx.lookAhead = 0.12;
66	    this.ctx = ctx;
67	    this.transport = Tone.getTransport();
68	    this.widener = new Tone.StereoWidener(0.5);
69	    this.master = new Tone.Gain(this.volumeGain());
70	    this.fade = new Tone.Gain(0);
71	    this.recorderTap = new Tone.Gain(1);
72	    this.widener.chain(this.master, this.fade, this.recorderTap, Tone.getDestination());
73	    this.unlocked = true;
74	  }
75	
76	  get context(): Ctx {
77	    return this.ctx ?? Tone.getContext();
78	  }
79	
80	  private get tr(): Transport {
81	    return this.transport ?? Tone.getTransport();
82	  }
83	
84	  private now() {
85	    return this.context.now();
86	  }
87	
88	  /** the audible position in seconds (the transport runs a little ahead by the look-ahead) */
89	  position(): number {
90	    if (!this.score) return 0;
91	    const t = this.tr;
92	    if (t.state === 'stopped') return 0;
93	    return Math.max(0, t.seconds - this.context.lookAhead);
94	  }
95	
96	  get loaded(): Score | null {
97	    return this.score;
98	  }
99	
100	  /** tap for live session recording */
101	  get tap(): Tone.Gain | null {
102	    return this.recorderTap;
103	  }
104	
105	  /** resume the context, but never hang if the browser refuses (hidden tab): it resumes on the next tap */
106	  private async resume() {
107	    const raw = this.context.rawContext as AudioContext;
108	    if (raw.state === 'running') return;
109	    await Promise.race([raw.resume(), wait(1200)]);
110	  }
111	
112	  /**
113	   * Notes already handed to the audio graph (inside the look-ahead window) can still start a moment
114	   * from now. Anything new must be scheduled after them, or a voice would get an earlier start than
115	   * one it already has. This is the earliest safe time.
116	   */
117	  private settled(extra = 0.05) {
118	    return this.now() + this.context.lookAhead + extra;
119	  }
120	
121	  private get startOffset() {
122	    return `+${(this.context.lookAhead + 0.12).toFixed(3)}`;
123	  }
124	
125	  private volumeGain() {
126	    return this.settings.muted ? 0 : this.settings.volume * this.settings.volume;
127	  }
128	
129	  private queue(task: () => Promise<void>): Promise<void> {
130	    this.busy = this.busy.then(task, task);
131	    return this.busy;
132	  }
133	
134	  /** load a score (and the rack for its mood) without starting it */
135	  load(score: Score, seed: string): Promise<void> {
136	    return this.queue(async () => {
137	      await this.swap(score, seed, 0);
138	    });
139	  }
140	
141	  private async swap(score: Score, seed: string, at: number) {
142	    if (!this.widener) throw new Error('Audio is locked. Press Begin first.');
143	    const transport = this.tr;
144	    transport.cancel(0);
145	    if (!this.rack || this.rack.moodId !== score.moodId) {
146	      const old = this.rack;
147	      this.rack = createRack(score.moodId as MoodId, { bpm: score.bpm, ambience: this.settings.ambience, withAmbience: true, seed });
148	      this.rack.output.connect(this.widener);
149	      await this.rack.ready;
150	      if (old) {
151	        old.releaseAll(this.settled());
152	        const o = old;
153	        window.setTimeout(() => o.dispose(), 9000); // let reverb tails finish before freeing nodes
154	        o.output.disconnect();
155	      }
156	    } else {
157	      this.rack.releaseAll(this.settled());
158	      this.rack.setTempo(score.bpm);
159	      for (const [id, v] of Object.entries(this.settings.ambience)) this.rack.setAmbience(id as AmbienceId, v ?? 0, 1);
160	    }
161	    this.score = score;
162	    transport.bpm.value = score.bpm;
163	    scheduleScore(transport, this.rack, score, at);
164	    this.rack.scheduleAmbience(transport, 0);
165	    transport.seconds = at;
166	  }
167	
168	  play(): Promise<void> {
169	    return this.queue(async () => {
170	      if (!this.score || !this.rack || !this.fade) return;
171	      const transport = this.tr;
172	      if (this.state === 'paused' && this.context.rawContext.state === 'suspended') {
173	        await this.resume();
174	      }
175	      if (transport.state !== 'started') {
176	        const at = transport.seconds >= totalLength(this.score) ? 0 : transport.seconds;
177	        if (at === 0 && transport.seconds !== 0) {
178	          transport.cancel(0);
179	          scheduleScore(transport, this.rack, this.score, 0);
180	          this.rack.scheduleAmbience(transport, 0);
181	        }
182	        transport.seconds = at;
183	        if (at > 0) this.resumeSustained(at);
184	        transport.start(this.startOffset);
185	      }
186	      const now = this.now();
187	      this.fade.gain.cancelScheduledValues(now);
188	      this.fade.gain.setValueAtTime(this.fade.gain.value, now);
189	      this.fade.gain.linearRampToValueAtTime(1, now + FADE_IN);
190	      this.state = 'playing';
191	    });
192	  }
193	
194	  pause(): Promise<void> {
195	    return this.queue(async () => {
196	      if (this.state !== 'playing' || !this.fade) return;
197	      const now = this.now();
198	      this.fade.gain.cancelScheduledValues(now);
199	      this.fade.gain.setValueAtTime(this.fade.gain.value, now);
200	      this.fade.gain.linearRampToValueAtTime(0, now + FADE_OUT);
201	      this.state = 'paused';
202	      await wait(FADE_OUT * 1000 + 60);
203	      if (this.state !== 'paused') return;
204	      // suspending the context freezes every envelope and the transport exactly where they are
205	      await (this.context.rawContext as AudioContext).suspend();
206	    });
207	  }
208	
209	  /** jump to a time; sustained voices (drone, pad, bass) are re-voiced so the harmony continues */
210	  seek(seconds: number): Promise<void> {
211	    return this.queue(async () => {
212	      if (!this.score || !this.rack || !this.fade) return;
213	      const s = Math.max(0, Math.min(seconds, totalLength(this.score) - 0.5));
214	      const transport = this.tr;
215	      const playing = this.state === 'playing';
216	      if (playing) {
217	        const now = this.now();
218	        this.fade.gain.cancelScheduledValues(now);
219	        this.fade.gain.setValueAtTime(this.fade.gain.value, now);
220	        this.fade.gain.linearRampToValueAtTime(0, now + 0.25);
221	        await wait(280);
222	      }
223	      transport.stop();
224	      this.rack.releaseAll(this.settled());
225	      transport.cancel(0);
226	      scheduleScore(transport, this.rack, this.score, s);
227	      this.rack.scheduleAmbience(transport, 0);
228	      transport.seconds = s;
229	      if (playing) {
230	        this.resumeSustained(s);
231	        transport.start(this.startOffset);
232	        const now = this.now();
233	        this.fade.gain.cancelScheduledValues(now);
234	        this.fade.gain.setValueAtTime(0, now);
235	        this.fade.gain.linearRampToValueAtTime(1, now + 0.8);
236	      }
237	    });
238	  }
239	
240	  private resumeSustained(at: number) {
241	    if (!this.score || !this.rack) return;
242	    const now = this.now() + this.context.lookAhead + 0.12;
243	    for (const n of this.score.notes) {
244	      if ((n.voice === 'drone' || n.voice === 'bass') && n.time < at && n.time + n.duration > at + 0.5) this.rack.play(n, now, n.time + n.duration - at);
245	    }
246	    for (const c of this.score.chords) {
247	      if (c.time < at && c.time + c.duration > at + 0.5) this.rack.playChord(c, now, c.time + c.duration - at);
248	    }
249	  }
250	
251	  /** dip-crossfade into a new score: fade out, swap, fade in. Calm, never abrupt. */
252	  crossfadeTo(score: Score, seed: string, autoplay = true): Promise<void> {
253	    return this.queue(async () => {
254	      if (!this.fade) return;
255	      const wasPlaying = this.state === 'playing';
256	      if (wasPlaying) {
257	        const now = this.now();
258	        this.fade.gain.cancelScheduledValues(now);
259	        this.fade.gain.setValueAtTime(this.fade.gain.value, now);
260	        this.fade.gain.linearRampToValueAtTime(0, now + DIP);
261	        await wait(DIP * 1000 + 50);
262	      }
263	      const transport = this.tr;
264	      transport.stop();
265	      await this.swap(score, seed, 0);
266	      if (wasPlaying || autoplay) {
267	        if (this.context.rawContext.state === 'suspended') await this.resume();
268	        transport.start(this.startOffset);
269	        const now = this.now();
270	        this.fade.gain.cancelScheduledValues(now);
271	        this.fade.gain.setValueAtTime(0, now);
272	        this.fade.gain.linearRampToValueAtTime(1, now + FADE_IN);
273	        this.state = 'playing';
274	      }
275	    });
276	  }
277	
278	  setVolume(v: number) {
279	    this.settings.volume = Math.max(0, Math.min(1, v));
280	    this.master?.gain.rampTo(this.volumeGain(), 0.15);
281	  }
282	
283	  setMuted(m: boolean) {
284	    this.settings.muted = m;
285	    this.master?.gain.rampTo(this.volumeGain(), 0.3);
286	  }
287	
288	  setMono(on: boolean) {
289	    this.settings.mono = on;
290	    this.widener?.width.rampTo(on ? 0 : 0.5, 0.3);
291	  }
292	
293	  setAmbience(layer: AmbienceId, level: number) {
294	    this.settings.ambience = { ...this.settings.ambience, [layer]: level };
295	    this.rack?.setAmbience(layer, level, 1.2);
296	  }
297	
298	  setAllAmbience(levels: Partial<Record<AmbienceId, number>>) {
299	    this.settings.ambience = { ...levels };
300	  }
301	
302	  /** a long, gentle fade (sleep timer), then pause */
303	  async sleepFade(seconds: number) {
304	    if (!this.fade || this.state !== 'playing') return;
305	    const now = this.now();
306	    this.fade.gain.cancelScheduledValues(now);
307	    this.fade.gain.setValueAtTime(this.fade.gain.value, now);
308	    this.fade.gain.linearRampToValueAtTime(0, now + seconds);
309	    await wait(seconds * 1000);
310	    if (this.state === 'playing') {
311	      this.state = 'paused';
312	      await (this.context.rawContext as AudioContext).suspend();
313	    }
314	  }
315	
316	  dispose() {
317	    this.tr.cancel(0);
318	    this.tr.stop();
319	    this.rack?.dispose();
320	    this.rack = null;
321	    this.score = null;
322	    this.state = 'idle';
323	  }
324	}
