1	// The composer: RecursionTrace → Score. Pure and deterministic.
2	//
3	// Fractal form (SPEC §5.3): the call tree IS the musical form.
4	//   trunk (depth 0)        → the key: root + fifth drone for the whole piece, a low opening note
5	//   boughs (depth 1)       → sections; each one shifts the melody's register
6	//   depth 2                → phrases; each phrase gets one chord from the mood's progression
7	//   inner branches         → the melody (lead), stepping through scale degrees
8	//   twigs (maxDepth − 1)   → ornaments: quieter, higher
9	//   leaves (base case)     → bells: chord tones in the upper octave, long ring
10	//   return from a phrase   → cadence: one beat of rest while the pad re-swells
11	//   return from the root   → final cadence on the tonic, then a long tail
12	
13	import { clamp, createRng, lerp, type Rng } from '../random';
14	import type { RecursionTrace, TraceNode } from '../worlds/types';
15	import { getMood, type Mood, type MoodId } from './moods';
16	import type { Mode, NodeTiming, Score, ScoreChord, ScoreEvent, ScoreNote, Voice } from './score';
17	import { chordPcs, degreeToMidi, mod, nearestChordTone, SCALES, voiceLead, type Chord } from './theory';
18	
19	export interface MusicParams {
20	  moodId: MoodId;
21	  mode: Mode;
22	  /** tempo in BPM; undefined = the mood's tempo (auto-adjusted for very long or short trees) */
23	  bpm?: number;
24	  /** transpose the key, in semitones (−5..+6) */
25	  transpose?: number;
26	  /** multiplier on the mood's note-density cap (0.5..1.2) */
27	  density?: number;
28	  /** longest piece in seconds before deep levels are thinned */
29	  maxDuration?: number;
30	  /** shortest piece in seconds before the tempo slows down (auto tempo only) */
31	  minDuration?: number;
32	}
33	
34	export const TAIL_SECONDS = 10;
35	const LEAD_LO = 60;
36	const LEAD_HI = 84;
37	
38	type Role = 'trunk' | 'section' | 'phrase' | 'lead' | 'twig' | 'leaf';
39	
40	interface Ctx {
41	  trace: RecursionTrace;
42	  mood: Mood;
43	  keyPc: number;
44	  scale: number[];
45	  leadBase: number;
46	  rng: Rng;
47	  phraseDepth: number;
48	}
49	
50	export function roleOf(node: TraceNode, maxDepth: number, phraseDepth: number): Role {
51	  if (node.depth === 0) return 'trunk';
52	  if (phraseDepth === 2 && node.depth === 1) return 'section';
53	  if (node.depth === phraseDepth) return 'phrase';
54	  if (node.isLeaf) return 'leaf';
55	  if (maxDepth >= 4 && node.depth >= maxDepth - 1) return 'twig';
56	  return 'lead';
57	}
58	
59	/** chord pitch classes usable for long notes (Lydian's raised 4th is kept for short passing notes only) */
60	function hPcs(ctx: Ctx, chord: Chord): number[] {
61	  const pcs = chordPcs(chord, ctx.keyPc);
62	  if (ctx.mood.avoidPc === undefined) return pcs;
63	  const avoid = mod(ctx.keyPc + ctx.mood.avoidPc, 12);
64	  const safe = pcs.filter((pc) => pc !== avoid);
65	  return safe.length ? safe : pcs;
66	}
67	
68	const quantise = (beats: number) => Math.round(clamp(beats, 0.5, 2) * 2) / 2;
69	const leadBeats = (node: TraceNode) => quantise(lerp(0.5, 2, Math.sqrt(clamp(node.size, 0, 1))));
70	const melodicStep = (node: TraceNode) => clamp(Math.round(node.turn * 1.5 + 0.5), -2, 3);
71	
72	/** velocity envelope over the piece: rise over the first 25%, hold to 70%, ease to 0.75 */
73	function form(x: number): number {
74	  if (x < 0.25) return lerp(0.7, 1, x / 0.25);
75	  if (x < 0.7) return 1;
76	  return lerp(1, 0.75, (x - 0.7) / 0.3);
77	}
78	
79	export function composeScore(trace: RecursionTrace, music: MusicParams): Score {
80	  const mood = getMood(music.moodId);
81	  const keyPc = mod(mood.keyPc + (music.transpose ?? 0), 12);
82	  const scale = SCALES[mood.scale];
83	  const ctx: Ctx = {
84	    trace,
85	    mood,
86	    keyPc,
87	    scale,
88	    leadBase: 60 + keyPc,
89	    rng: createRng(`compose:${trace.seed}:${music.moodId}:${music.mode}`),
90	    phraseDepth: trace.maxDepth >= 4 ? 2 : 1,
91	  };
92	  const result = music.mode === 'bloom' ? composeBloom(ctx, music) : composeWander(ctx, music);
93	  return finalize(ctx, music, result);
94	}
95	
96	interface Draft {
97	  bpm: number;
98	  notes: ScoreNote[];
99	  chords: ScoreChord[];
100	  events: ScoreEvent[];
101	  nodeTimes: NodeTiming[];
102	  duration: number;
103	  thinned: number;
104	}
105	
106	// ───────────────────────────── Wander (depth-first) ─────────────────────────────
107	
108	function composeWander(ctx: Ctx, music: MusicParams): Draft {
109	  const { trace, mood } = ctx;
110	  const nodes = trace.nodes;
111	  const D = trace.maxDepth;
112	  const roles = nodes.map((n) => roleOf(n, D, ctx.phraseDepth));
113	
114	  // Pass 1: how many beats each node advances the cursor when it sounds.
115	  const advance = nodes.map((n, i) => {
116	    switch (roles[i]) {
117	      case 'trunk':
118	        return 4;
119	      case 'section':
120	        return 2;
121	      case 'phrase':
122	        return 3; // 2-beat phrase head + 1 beat of cadence rest on return
123	      case 'lead':
124	        return leadBeats(n);
125	      default:
126	        return 0.5;
127	    }
128	  });
129	  const FINAL_BEATS = 8;
130	  let totalBeats = advance.reduce((a, b) => a + b, 0) + FINAL_BEATS;
131	
132	  // Fit the piece into the target length: tempo first, then thin the deepest levels.
133	  const maxDur = music.maxDuration ?? 300;
134	  const minDur = music.minDuration ?? 90;
135	  let bpm = music.bpm ?? mood.bpm;
136	  if (music.bpm === undefined) {
137	    const sec = (totalBeats * 60) / bpm;
138	    if (sec > maxDur) bpm = Math.min(bpm * 1.15, mood.bpmRange[1]);
139	    else if (sec < minDur) bpm = Math.max(mood.bpmRange[0], (totalBeats * 60) / minDur);
140	  }
141	  const targetBeats = (maxDur * bpm) / 60;
142	  const keep = Array.from({ length: nodes.length }, () => true);
143	  let thinned = 0;
144	  if (totalBeats > targetBeats) {
145	    // groups in thinning order: leaves, twigs, then lead levels from the deepest up
146	    const leadDepths = [...new Set(nodes.filter((_, i) => roles[i] === 'lead').map((n) => n.depth))].sort((a, b) => b - a);
147	    const groups: Array<{ ids: number[]; floor: number }> = [
148	      { ids: nodes.filter((_, i) => roles[i] === 'leaf').map((n) => n.id), floor: 0.15 },
149	      { ids: nodes.filter((_, i) => roles[i] === 'twig').map((n) => n.id), floor: 0.12 },
150	      ...leadDepths.map((d) => ({ ids: nodes.filter((n, i) => roles[i] === 'lead' && n.depth === d).map((n) => n.id), floor: 0.25 })),
151	    ];
152	    for (const g of groups) {
153	      if (totalBeats <= targetBeats || g.ids.length === 0) continue;
154	      const groupBeats = g.ids.reduce((a, id) => a + advance[id], 0);
155	      const ratio = clamp(1 - (totalBeats - targetBeats) / groupBeats, g.floor, 1);
156	      // Bresenham selection: evenly spread, deterministic
157	      let acc = 0.5;
158	      for (const id of g.ids) {
159	        acc += ratio;
160	        if (acc >= 1) acc -= 1;
161	        else {
162	          keep[id] = false;
163	          totalBeats -= advance[id];
164	          thinned++;
165	        }
166	      }
167	    }
168	  }
169	
170	  const beat = 60 / bpm;
171	  const estTotal = totalBeats * beat;
172	  const notes: ScoreNote[] = [];
173	  const chords: ScoreChord[] = [];
174	  const events: ScoreEvent[] = [];
175	  const nodeTimes: NodeTiming[] = nodes.map(() => ({ start: 0, grow: beat, sounding: false }));
176	  const deg = Array.from({ length: nodes.length }, () => 0);
177	  const rng = ctx.rng.fork('wander');
178	
179	  let cursor = 0; // beats
180	  let chord: Chord = mood.tonic;
181	  let pcs = hPcs(ctx, chord);
182	  let voicing: number[] | null = null;
183	  let phraseCount = 0;
184	  let sectionCount = 0;
185	  let lastLead = ctx.leadBase + 7;
186	  let lastBell = -1;
187	  let repeat = 0;
188	
189	  const panOf = (n: TraceNode) => {
190	    const b = trace.bounds;
191	    const cx = (b.minX + b.maxX) / 2;
192	    const half = Math.max(1, (b.maxX - b.minX) / 2);
193	    const x = n.points.length ? n.points[n.points.length - 2] : cx;
194	    return clamp(((x - cx) / half) * 0.7, -0.7, 0.7);
195	  };
196	  const vel = (depth: number, tSec: number, scale = 1) =>
197	    clamp(0.62 * Math.pow(0.92, depth) * form(tSec / Math.max(estTotal, 1)) * (1 + rng.jitter(0.08)) * scale, 0.12, 0.85);
198	
199	  const fitRange = (d: number): number => {
200	    const n = ctx.scale.length;
201	    let m = degreeToMidi(d, ctx.scale, ctx.leadBase);
202	    while (m > LEAD_HI) {
203	      d -= n;
204	      m = degreeToMidi(d, ctx.scale, ctx.leadBase);
205	    }
206	    while (m < LEAD_LO) {
207	      d += n;
208	      m = degreeToMidi(d, ctx.scale, ctx.leadBase);
209	    }
210	    return d;
211	  };
212	
213	  const addNote = (voice: Voice, node: TraceNode, timeBeats: number, durBeats: number, midi: number, velocity: number, humanise: number) => {
214	    const time = Math.max(0, timeBeats * beat + rng.jitter(humanise));
215	    notes.push({ time, duration: durBeats * beat, midi, velocity, pan: panOf(node), voice, nodeId: node.id, depth: node.depth });
216	  };
217	
218	  /** choose the lead pitch for a node: scale degree walk, chord-tone snap, range, no long repeats */
219	  const leadPitch = (node: TraceNode, snap: boolean, durBeats: number): number => {
220	    const strong = mod(cursor, 2) < 0.01;
221	    let d = deg[node.id];
222	    let midi = degreeToMidi(d, ctx.scale, ctx.leadBase);
223	    if (snap || strong) midi = nearestChordTone(midi, pcs, ctx.scale, ctx.leadBase);
224	    if (ctx.mood.avoidPc !== undefined && mod(midi - ctx.keyPc, 12) === ctx.mood.avoidPc && (strong || durBeats > 1)) {
225	      midi = nearestChordTone(midi, pcs, ctx.scale, ctx.leadBase);
226	    }
227	    if (midi === lastLead) {
228	      repeat++;
229	      if (repeat >= 3) {
230	        d += rng.chance(0.5) ? 1 : -1;
231	        d = fitRange(d);
232	        midi = degreeToMidi(d, ctx.scale, ctx.leadBase);
233	        repeat = 0;
234	      }
235	    } else repeat = 0;
236	    lastLead = midi;
237	    return midi;
238	  };
239	
240	  let phraseStart = 0;
241	  for (const ev of trace.events) {
242	    const node = nodes[ev.nodeId];
243	    const role = roles[node.id];
244	    const tSec = cursor * beat;
245	
246	    if (ev.kind === 'call') {
247	      events.push({ time: tSec, kind: 'call', nodeId: node.id, depth: node.depth });
248	      // the melodic degree is inherited from the parent and stepped by the branch's turn
249	      if (node.parentId !== null) {
250	        let d = deg[node.parentId] + melodicStep(node);
251	        if (rng.chance(((trace.params.randomness ?? 0.25) as number) * 0.5)) d += rng.chance(0.5) ? 1 : -1;
252	        if (role === 'section') d += [0, 2, -1, 3, 1][sectionCount % 5];
253	        deg[node.id] = fitRange(d);
254	      } else deg[node.id] = fitRange(2);
255	
256	      if (!keep[node.id]) {
257	        nodeTimes[node.id] = { start: tSec, grow: beat * 0.75, sounding: false };
258	        continue;
259	      }
260	      switch (role) {
261	        case 'trunk': {
262	          nodeTimes[node.id] = { start: 0, grow: 4 * beat, sounding: true };
263	          addNote('bass', node, 0, 6, ctx.keyPc + 36 + 12 * (ctx.keyPc < 4 ? 1 : 0), 0.42, 0);
264	          cursor += 4;
265	          break;
266	        }
267	        case 'section': {
268	          sectionCount++;
269	          events.push({ time: tSec, kind: 'section', nodeId: node.id, depth: node.depth });
270	          nodeTimes[node.id] = { start: tSec, grow: 2 * beat, sounding: true };
271	          addNote('lead', node, cursor, 2, leadPitch(node, true, 2), vel(node.depth, tSec, 0.85), 0.01);
272	          cursor += 2;
273	          break;
274	        }
275	        case 'phrase': {
276	          chord = ctx.mood.progression[phraseCount % ctx.mood.progression.length];
277	          phraseCount++;
278	          pcs = hPcs(ctx, chord);
279	          voicing = voiceLead(chord, ctx.keyPc, voicing);
280	          phraseStart = tSec;
281	          chords.push({ time: tSec, duration: 8 * beat, midis: voicing, symbol: chord.symbol });
282	          const root = mod(ctx.keyPc + chord.tones[0], 12);
283	          addNote('bass', node, cursor, 4, 36 + root + (root < 4 ? 12 : 0), 0.38, 0);
284	          nodeTimes[node.id] = { start: tSec, grow: 2 * beat, sounding: true };
285	          addNote('lead', node, cursor, 2.2, leadPitch(node, true, 2), vel(node.depth, tSec), 0.01);
286	          cursor += 2;
287	          break;
288	        }
289	        case 'lead': {
290	          const b = leadBeats(node);
291	          nodeTimes[node.id] = { start: tSec, grow: b * beat, sounding: true };
292	          addNote('lead', node, cursor, b * 1.15, leadPitch(node, false, b), vel(node.depth, tSec), 0.012);
293	          cursor += b;
294	          break;
295	        }
296	        case 'twig': {
297	          const d = deg[node.id] + 2;
298	          let m = degreeToMidi(d, ctx.scale, ctx.leadBase);
299	          if (m > 88) m -= 12;
300	          nodeTimes[node.id] = { start: tSec, grow: 0.5 * beat, sounding: true };
301	          addNote('ornament', node, cursor, 1, m, vel(node.depth, tSec, 0.7), 0.015);
302	          cursor += 0.5;
303	          break;
304	        }
305	        case 'leaf': {
306	          // each leaf rings the chord tone nearest its own branch's degree, an octave up
307	          let m = nearestChordTone(degreeToMidi(deg[node.id], ctx.scale, ctx.leadBase) + 12, pcs, ctx.scale, ctx.leadBase);
308	          if (m === lastBell) m = nearestChordTone(m + (node.childIndex % 2 === 0 ? -3 : 3), pcs, ctx.scale, ctx.leadBase);
309	          while (m > 88) m -= 12;
310	          while (m < 72) m += 12;
311	          lastBell = m;
312	          nodeTimes[node.id] = { start: tSec, grow: 0.5 * beat, sounding: true };
313	          addNote('bell', node, cursor, 4, m, vel(node.depth, tSec, 0.9), 0.02);
314	          cursor += 0.5;
315	          break;
316	        }
317	      }
318	    } else {
319	      events.push({ time: tSec, kind: 'return', nodeId: node.id, depth: node.depth });
320	      if (role === 'phrase' && keep[node.id]) {
321	        events.push({ time: tSec, kind: 'cadence', nodeId: node.id, depth: node.depth });
322	        cursor += 1; // the phrase breathes
323	        const last = chords[chords.length - 1];
324	        if (last) last.duration = Math.max(last.duration, cursor * beat - phraseStart + 1.5 * beat);
325	      }
326	      if (role === 'trunk') {
327	        // final cadence: home chord, a last bell, the drone keeps ringing into the tail
328	        const tonicVoicing = voiceLead(mood.tonic, ctx.keyPc, voicing);
329	        chords.push({ time: tSec, duration: FINAL_BEATS * beat + 4, midis: tonicVoicing, symbol: mood.tonic.symbol });
330	        events.push({ time: tSec, kind: 'cadence', nodeId: node.id, depth: 0 });
331	        addNote('bass', node, cursor, FINAL_BEATS, ctx.keyPc + 36 + (ctx.keyPc < 4 ? 12 : 0), 0.4, 0);
332	        addNote('bell', node, cursor + 1, 6, nearestChordTone(ctx.leadBase + 12, hPcs(ctx, mood.tonic), ctx.scale, ctx.leadBase), 0.4, 0);
333	        cursor += FINAL_BEATS;
334	      }
335	    }
336	  }
337	
338	  // let each pad chord sustain until the next one begins, with a short overlap
339	  for (let i = 0; i < chords.length - 1; i++) {
340	    const gap = chords[i + 1].time - chords[i].time;
341	    chords[i].duration = Math.max(chords[i].duration, gap + beat);
342	  }
343	
344	  return { bpm, notes, chords, events, nodeTimes, duration: cursor * beat, thinned };
345	}
346	
347	// ───────────────────────────── Bloom (breadth-first) ─────────────────────────────
348	
349	function composeBloom(ctx: Ctx, music: MusicParams): Draft {
350	  const { trace, mood } = ctx;
351	  const nodes = trace.nodes;
352	  const D = trace.maxDepth;
353	  const bpm = music.bpm ?? mood.bpm;
354	  const beat = 60 / bpm;
355	  const rng = ctx.rng.fork('bloom');
356	  const levels: TraceNode[][] = Array.from({ length: D + 1 }, () => []);
357	  for (const n of nodes) levels[n.depth].push(n);
358	  const endX = (n: TraceNode) => (n.points.length ? n.points[n.points.length - 2] : 0);
359	  for (const l of levels) l.sort((a, b) => endX(a) - endX(b));
360	
361	  const phraseLevels = Math.max(1, D - 1);
362	  const beatsPerLevel = clamp(Math.round(((150 / beat) / phraseLevels) / 4) * 4, 8, 16);
363	
364	  const notes: ScoreNote[] = [];
365	  const chords: ScoreChord[] = [];
366	  const events: ScoreEvent[] = [];
367	  const nodeTimes: NodeTiming[] = nodes.map(() => ({ start: 0, grow: beat, sounding: false }));
368	  const b = trace.bounds;
369	  const cx = (b.minX + b.maxX) / 2;
370	  const half = Math.max(1, (b.maxX - b.minX) / 2);
371	  const pan = (n: TraceNode) => clamp(((endX(n) - cx) / half) * 0.7, -0.7, 0.7);
372	  const push = (voice: Voice, n: TraceNode, tBeats: number, durBeats: number, midi: number, velocity: number, h = 0) =>
373	    notes.push({ time: Math.max(0, tBeats * beat + rng.jitter(h)), duration: durBeats * beat, midi, velocity, pan: pan(n), voice, nodeId: n.id, depth: n.depth });
374	
375	  let cursor = 0;
376	  let voicing: number[] | null = null;
377	  // level 0: the trunk and the drone
378	  const trunk = levels[0][0];
379	  nodeTimes[trunk.id] = { start: 0, grow: 4 * beat, sounding: true };
380	  events.push({ time: 0, kind: 'call', nodeId: trunk.id, depth: 0 });
381	  push('bass', trunk, 0, 6, ctx.keyPc + 36 + (ctx.keyPc < 4 ? 12 : 0), 0.42);
382	  cursor = 4;
383	
384	  const estTotal = (4 + 4 + beatsPerLevel * phraseLevels + 8) * beat;
385	  for (let d = 1; d <= D; d++) {
386	    const level = levels[d];
387	    if (level.length === 0) continue;
388	    const isFirst = d === 1;
389	    const span = isFirst ? 4 : beatsPerLevel;
390	    const chord = isFirst ? mood.tonic : mood.progression[(d - 2) % mood.progression.length];
391	    voicing = voiceLead(chord, ctx.keyPc, voicing);
392	    const pcs = hPcs(ctx, chord);
393	    chords.push({ time: cursor * beat, duration: (span + 1) * beat, midis: voicing, symbol: chord.symbol });
394	    events.push({ time: cursor * beat, kind: 'section', nodeId: level[0].id, depth: d });
395	    const root = mod(ctx.keyPc + chord.tones[0], 12);
396	    push('bass', level[0], cursor, Math.min(span, 8), 36 + root + (root < 4 ? 12 : 0), 0.36);
397	
398	    // chord tones in a register that rises one step per level
399	    const lo = clamp(ctx.leadBase - 3 + (d - 1) * 2, 55, 74);
400	    const tones: number[] = [];
401	    for (let m = lo; m <= lo + 17; m++) if (pcs.includes(mod(m, 12)) && SCALES[mood.scale].some((s) => mod(ctx.keyPc + s, 12) === mod(m, 12))) tones.push(m);
402	    if (tones.length === 0) tones.push(nearestChordTone(lo + 7, pcs, ctx.scale, ctx.leadBase));
403	
404	    const m = level.length;
405	    const soundCount = Math.min(12, m);
406	    const soundEvery = m / soundCount;
407	    let nextSound = 0;
408	    let soundIdx = 0;
409	    const isLeafLevel = d === D;
410	    const voice: Voice = isLeafLevel && D >= 2 ? 'bell' : 'lead';
411	    level.forEach((n, i) => {
412	      const slot = cursor + (i / m) * span + (m > 1 ? rng.jitter(0.15) : 0);
413	      const t = Math.max(cursor, slot);
414	      events.push({ time: t * beat, kind: 'call', nodeId: n.id, depth: d });
415	      const sounding = i >= nextSound - 1e-9;
416	      nodeTimes[n.id] = { start: t * beat, grow: Math.max(0.5, span / m) * beat * 1.5, sounding };
417	      if (sounding) {
418	        nextSound += soundEvery;
419	        const k = soundCount === 1 ? Math.floor(tones.length / 2) : Math.round((soundIdx / (soundCount - 1)) * (tones.length - 1));
420	        let midi = tones[k];
421	        if (voice === 'bell') while (midi < 72) midi += 12;
422	        const durB = voice === 'bell' ? 4 : clamp((span / soundCount) * 1.5, 1, 3);
423	        const v = clamp(0.62 * Math.pow(0.92, d) * form((t * beat) / estTotal) * (1 + rng.jitter(0.08)), 0.12, 0.85);
424	        push(voice, n, t, durB, midi, voice === 'bell' ? v * 0.9 : v, voice === 'bell' ? 0.02 : 0.012);
425	        soundIdx++;
426	      }
427	    });
428	    cursor += span;
429	    events.push({ time: cursor * beat, kind: 'cadence', nodeId: level[level.length - 1].id, depth: d });
430	  }
431	
432	  const tonicVoicing = voiceLead(mood.tonic, ctx.keyPc, voicing);
433	  chords.push({ time: cursor * beat, duration: 8 * beat + 4, midis: tonicVoicing, symbol: mood.tonic.symbol });
434	  push('bass', trunk, cursor, 8, ctx.keyPc + 36 + (ctx.keyPc < 4 ? 12 : 0), 0.4);
435	  push('bell', trunk, cursor + 1, 6, nearestChordTone(ctx.leadBase + 12, hPcs(ctx, mood.tonic), ctx.scale, ctx.leadBase), 0.4);
436	  events.push({ time: cursor * beat, kind: 'return', nodeId: trunk.id, depth: 0 });
437	  cursor += 8;
438	
439	  for (let i = 0; i < chords.length - 1; i++) {
440	    const gap = chords[i + 1].time - chords[i].time;
441	    chords[i].duration = Math.max(chords[i].duration, gap + beat);
442	  }
443	  return { bpm, notes, chords, events, nodeTimes, duration: cursor * beat, thinned: 0 };
444	}
445	
446	// ───────────────────────────── shared finishing ─────────────────────────────
447	
448	function finalize(ctx: Ctx, music: MusicParams, d: Draft): Score {
449	  const cap = ctx.mood.maxNotesPerSecond * (music.density ?? 1);
450	  const { kept, dropped } = applyDensityCap(d.notes, cap);
451	  // the drone holds the key for the whole piece and fades into the tail
452	  const droneRoot = 36 + ctx.keyPc + (ctx.keyPc < 2 ? 12 : 0);
453	  const trunkId = ctx.trace.nodes[0]?.id ?? 0;
454	  const droneDur = d.duration + TAIL_SECONDS * 0.6;
455	  kept.push({ time: 0, duration: droneDur, midi: droneRoot, velocity: 0.5, pan: -0.15, voice: 'drone', nodeId: trunkId, depth: 0 });
456	  kept.push({ time: 0, duration: droneDur, midi: droneRoot + 7, velocity: 0.42, pan: 0.15, voice: 'drone', nodeId: trunkId, depth: 0 });
457	  kept.sort((a, b) => a.time - b.time || a.midi - b.midi);
458	  d.events.sort((a, b) => a.time - b.time);
459	  for (const n of kept) {
460	    n.time = round(n.time);
461	    n.duration = round(Math.max(0.05, n.duration));
462	  }
463	  // mark nodes whose note was dropped by the density cap as silent (they still grow)
464	  const soundingIds = new Set(kept.map((n) => n.nodeId));
465	  for (let i = 0; i < d.nodeTimes.length; i++) if (d.nodeTimes[i].sounding && !soundingIds.has(i)) d.nodeTimes[i].sounding = false;
466	
467	  return {
468	    version: 1,
469	    seed: ctx.trace.seed,
470	    worldId: ctx.trace.worldId,
471	    moodId: ctx.mood.id,
472	    mode: music.mode,
473	    bpm: Math.round(d.bpm * 10) / 10,
474	    key: `${['C', 'C♯', 'D', 'E♭', 'E', 'F', 'F♯', 'G', 'A♭', 'A', 'B♭', 'B'][ctx.keyPc]}`,
475	    scale: ctx.mood.scale,
476	    duration: round(d.duration),
477	    tail: TAIL_SECONDS,
478	    notes: kept,
479	    chords: d.chords,
480	    events: d.events,
481	    nodeTimes: d.nodeTimes,
482	    stats: { noteCount: kept.length, nodeCount: ctx.trace.nodes.length, maxDepth: ctx.trace.maxDepth, droppedForDensity: dropped, thinned: d.thinned },
483	  };
484	}
485	
486	const round = (x: number) => Math.round(x * 1000) / 1000;
487	const ATTACK_VOICES: Voice[] = ['lead', 'bell', 'ornament'];
488	
489	/**
490	 * Keep at most `cap` attacked notes (lead, bell, ornament) in any 1-second window.
491	 * Accept in priority order — lead, then bells, then ornaments — so the lowest-priority
492	 * notes are the ones dropped. Drone, pad and bass are never dropped.
493	 */
494	export function applyDensityCap(notes: ScoreNote[], cap: number): { kept: ScoreNote[]; dropped: number } {
495	  const limit = Math.max(1, Math.floor(cap));
496	  const accepted: number[] = []; // sorted times of accepted attack notes
497	  const kept: ScoreNote[] = notes.filter((n) => !ATTACK_VOICES.includes(n.voice));
498	  let dropped = 0;
499	  for (const voice of ATTACK_VOICES) {
500	    const cands = notes.filter((n) => n.voice === voice).sort((a, b) => a.time - b.time);
501	    for (const n of cands) {
502	      if (fits(accepted, n.time, limit)) {
503	        insertSorted(accepted, n.time);
504	        kept.push(n);
505	      } else dropped++;
506	    }
507	  }
508	  return { kept, dropped };
509	}
510	
511	function fits(sorted: number[], t: number, limit: number): boolean {
512	  // every 1 s window that would contain t must hold fewer than `limit` accepted notes;
513	  // the worst window starts at t or at an accepted note in (t − 1, t]
514	  const lo = lowerBound(sorted, t - 1 + 1e-9);
515	  const starts = [t];
516	  for (let i = lo; i < sorted.length && sorted[i] <= t; i++) starts.push(sorted[i]);
517	  for (const s of starts) {
518	    const a = lowerBound(sorted, s);
519	    const b = lowerBound(sorted, s + 1 - 1e-9);
520	    if (b - a + 1 > limit) return false;
521	  }
522	  return true;
523	}
524	
525	function lowerBound(xs: number[], v: number): number {
526	  let lo = 0;
527	  let hi = xs.length;
528	  while (lo < hi) {
529	    const mid = (lo + hi) >> 1;
530	    if (xs[mid] < v) lo = mid + 1;
531	    else hi = mid;
532	  }
533	  return lo;
534	}
535	
536	function insertSorted(xs: number[], v: number) {
537	  xs.splice(lowerBound(xs, v), 0, v);
538	}
