261	    const g = ctx.createLinearGradient(0, 0, 0, h);
262	    g.addColorStop(0, rgba(pal.bg0));
263	    g.addColorStop(0.65, rgba(pal.bg1));
264	    g.addColorStop(1, rgba(mixRgb(pal.bg1, pal.horizon, 0.12)));
