270	    hg.addColorStop(0, rgba(pal.horizon, 0.2 + 0.05 * breathe));
271	    hg.addColorStop(0.45, rgba(pal.horizon, 0.06));
272	    hg.addColorStop(1, rgba(pal.horizon, 0));
273	    ctx.fillStyle = hg;
274	    ctx.fillRect(0, 0, w, h);
