291	  private drawScene(scene: Scene, t: number, wall: number, alpha: number, live: boolean) {
292	    const { ctx, pal } = this;
293	    const cam = live ? this.camera(scene, wall) : this.cam;
294	    const b = scene.bounds;
295	    const height = Math.max(1, b.maxY - b.minY);
296	    const baseY = b.maxY;
297	    const amp = this.reducedMotion || this.opts.staticMode ? 0 : height * 0.011;
298	    const T = wall;
299	    const swayX = (x: number, y: number) => {
300	      if (amp === 0) return 0;
301	      const hh = clamp01((baseY - y) / height);
302	      return (Math.sin(T * 0.78 + y * 0.011) * 0.65 + Math.sin(T * 0.43 + x * 0.013 + 1.7) * 0.35) * amp * Math.pow(hh, 1.6);
303	    };
304	    const sx = (x: number, y: number) => (x + swayX(x, y)) * cam.s + cam.x;
305	    const sy = (y: number) => y * cam.s + cam.y;
306	    const D = Math.max(1, scene.maxDepth);
307	
308	    ctx.lineCap = 'round';
309	    ctx.lineJoin = 'round';
310	    const paths: Path2D[] = [];
311	    const widths: number[] = [];
312	    const active: Array<{ i: number; glow: number }> = [];
313	    for (let d = 0; d <= scene.maxDepth; d++) {
314	      const path = new Path2D();
315	      let any = false;
316	      let wsum = 0;
317	      let wcount = 0;
318	      for (const id of scene.byDepth[d]) {
319	        const n = scene.nodes[id];
320	        const raw = (t - n.start) / n.grow;
321	        if (raw <= 0) continue;
322	        const p = easeOutCubic(clamp01(raw));
323	        const target = p * n.total;
324	        const pts = n.pts;
325	        path.moveTo(sx(pts[0], pts[1]), sy(pts[1]));
326	        for (let k = 1; k < n.cum.length; k++) {
327	          if (n.cum[k] <= target) {
328	            path.lineTo(sx(pts[k * 2], pts[k * 2 + 1]), sy(pts[k * 2 + 1]));
329	          } else {
330	            const seg = n.cum[k] - n.cum[k - 1];
331	            const f = seg > 0 ? (target - n.cum[k - 1]) / seg : 1;
332	            const x = pts[k * 2 - 2] + (pts[k * 2] - pts[k * 2 - 2]) * f;
333	            const y = pts[k * 2 - 1] + (pts[k * 2 + 1] - pts[k * 2 - 1]) * f;
334	            path.lineTo(sx(x, y), sy(y));
335	            break;
336	          }
337	        }
338	        any = true;
339	        wsum += n.width;
340	        wcount++;
341	        if (n.noteTime >= 0 && t >= n.noteTime && t - n.noteTime < 2.2) {
342	          const x = t - n.noteTime;
343	          const env = x < 0.08 ? x / 0.08 : Math.exp(-(x - 0.08) / 0.7);
344	          active.push({ i: id, glow: env * (0.5 + n.noteVel) });
345	        }
346	      }
347	      paths.push(any ? path : new Path2D());
348	      widths.push(wcount ? wsum / wcount : 1);
349	    }
350	
351	    // trunk-to-tip colour; a wide, low-alpha 'lighter' pass adds the glow
352	    ctx.globalAlpha = alpha;
353	    for (let d = 0; d < paths.length; d++) {
354	      const f = d / D;
355	      ctx.strokeStyle = rgba(mixRgb(pal.trunk, pal.tip, 0.16 + 0.84 * Math.pow(f, 0.9)), 0.96);
356	      ctx.lineWidth = Math.max(0.7, widths[d] * cam.s * 0.9);
357	      ctx.stroke(paths[d]);
358	    }
359	    ctx.globalCompositeOperation = 'lighter';
360	    for (let d = 1; d < paths.length; d++) {
361	      const f = d / D;
362	      ctx.strokeStyle = rgba(mixRgb(pal.accent, pal.tip, f), 0.045 + 0.075 * f);
363	      ctx.lineWidth = Math.min(14, Math.max(2.5, widths[d] * cam.s * 1.7 + 3));
364	      ctx.stroke(paths[d]);
365	    }
366	    // the branches whose notes are sounding brighten with the note's loudness
367	    for (const a of active) {
368	      const n = scene.nodes[a.i];
369	      const pts = n.pts;
370	      ctx.beginPath();
371	      ctx.moveTo(sx(pts[0], pts[1]), sy(pts[1]));
372	      for (let k = 1; k < n.cum.length; k++) ctx.lineTo(sx(pts[k * 2], pts[k * 2 + 1]), sy(pts[k * 2 + 1]));
373	      ctx.strokeStyle = rgba(mixRgb(pal.tip, [255, 255, 255], 0.35), 0.35 * a.glow);
374	      ctx.lineWidth = Math.max(2, n.width * cam.s * 1.6 + 2);
375	      ctx.stroke();
376	    }
377	
378	    // blossoms open when their bell rings, then breathe slowly
379	    if (this.blossomSprite) {
380	      const sprite = this.blossomSprite;
381	      const base = Math.max(7, Math.min(18, cam.s * (scene.trace.worldId === 'grove' ? 3.2 : 4.5)));
382	      for (let i = 0; i < scene.nodes.length; i++) {
383	        const n = scene.nodes[i];
384	        if (!n.leaf) continue;
385	        const open = n.bellTime >= 0 ? n.bellTime : n.start + n.grow;
386	        const x = t - open;
387	        if (x <= 0) continue;
388	        const s = easeOutCubic(clamp01(x / 1.4));
389	        const breathe = this.reducedMotion ? 0.85 : 0.7 + 0.3 * (0.5 + 0.5 * Math.sin((wall * Math.PI * 2) / (6 + (i % 5)) + i * 0.7));
390	        const ring = n.bellTime >= 0 && x < 2.5 ? Math.exp(-x / 0.9) * 0.6 : 0;
391	        const size = base * (n.bellTime >= 0 ? 1 : 0.6) * s * (1 + ring);
392	        const k = n.pts.length - 2;
393	        const px = sx(n.pts[k], n.pts[k + 1]);
394	        const py = sy(n.pts[k + 1]);
395	        ctx.globalAlpha = alpha * Math.min(1, breathe + ring);
396	        ctx.drawImage(sprite, px - size, py - size, size * 2, size * 2);
397	      }
398	    }
399	    ctx.globalAlpha = 1;
400	    ctx.globalCompositeOperation = 'source-over';
401	  }
