411	        this.sparks.push({
412	          x: n.pts[k] * cam.s + cam.x,
413	          y: n.pts[k + 1] * cam.s + cam.y,
414	          vx: rng.range(-9, 9),
415	          vy: rng.range(-16, -5),
416	          born: wall,
417	          life: rng.range(1.6, 2.6),
418	        });
419	      }
420	    }
