423	  private drawSparks(wall: number) {
424	    if (!this.glowSprite || this.sparks.length === 0) return;
425	    const { ctx } = this;
426	    ctx.globalCompositeOperation = 'lighter';
427	    this.sparks = this.sparks.filter((s) => wall - s.born < s.life);
428	    for (const s of this.sparks) {
429	      const age = wall - s.born;
430	      const a = Math.sin(Math.PI * clamp01(age / s.life)) * 0.8;
431	      const x = s.x + s.vx * age;
432	      const y = s.y + s.vy * age;
433	      ctx.globalAlpha = a;
434	      ctx.drawImage(this.glowSprite, x - 6, y - 6, 12, 12);
435	    }
436	    ctx.globalAlpha = 1;
437	    ctx.globalCompositeOperation = 'source-over';
438	  }
