440	  private drawFireflies(wall: number) {
441	    if (!this.glowSprite) return;
442	    const { ctx, w, h } = this;
443	    ctx.globalCompositeOperation = 'lighter';
444	    for (const f of this.flies) {
445	      const T = this.reducedMotion ? 0 : wall;
446	      const x = (f.x + Math.sin(T * f.fx * Math.PI * 2 + f.p) * f.ax) * w;
447	      const y = (f.y + Math.cos(T * f.fy * Math.PI * 2 + f.p * 1.3) * f.ay) * h;
448	      const glow = this.reducedMotion ? 0.35 : Math.pow(0.5 + 0.5 * Math.sin(wall * f.f * Math.PI * 2 + f.p), 3);
449	      ctx.globalAlpha = 0.12 + 0.55 * glow;
450	      const s = 6 + f.r * 4;
451	      ctx.drawImage(this.glowSprite, x - s, y - s, s * 2, s * 2);
452	    }
453	    ctx.globalAlpha = 1;
454	    ctx.globalCompositeOperation = 'source-over';
