259	  private drawSky(wall: number) {
260	    const { ctx, w, h, pal } = this;
261	    const g = ctx.createLinearGradient(0, 0, 0, h);
262	    g.addColorStop(0, rgba(pal.bg0));
263	    g.addColorStop(0.65, rgba(pal.bg1));
264	    g.addColorStop(1, rgba(mixRgb(pal.bg1, pal.horizon, 0.12)));
265	    ctx.fillStyle = g;
266	    ctx.fillRect(0, 0, w, h);
267	    // horizon glow, breathing on a 10 s cycle
268	    const breathe = this.reducedMotion ? 0.5 : 0.5 + 0.5 * Math.sin((wall * Math.PI * 2) / 10);
269	    const hg = ctx.createRadialGradient(w / 2, h * 1.08, 0, w / 2, h * 1.08, Math.max(w, h) * 0.75);
270	    hg.addColorStop(0, rgba(pal.horizon, 0.2 + 0.05 * breathe));
271	    hg.addColorStop(0.45, rgba(pal.horizon, 0.06));
272	    hg.addColorStop(1, rgba(pal.horizon, 0));
273	    ctx.fillStyle = hg;
274	    ctx.fillRect(0, 0, w, h);
275	    // stars, slowly twinkling
276	    for (const s of this.stars) {
277	      const tw = this.reducedMotion ? 0.6 : 0.45 + 0.55 * (0.5 + 0.5 * Math.sin(wall * s.f * Math.PI * 2 + s.p));
278	      ctx.fillStyle = `rgba(238,241,248,${0.5 * tw})`;
279	      ctx.beginPath();
280	      ctx.arc(s.x * w, s.y * h, s.r, 0, Math.PI * 2);
281	      ctx.fill();
282	    }
283	    // ground mist
284	    const mg = ctx.createLinearGradient(0, h * 0.78, 0, h);
285	    mg.addColorStop(0, rgba(pal.bg1, 0));
286	    mg.addColorStop(1, rgba(mixRgb(pal.bg1, pal.horizon, 0.08), 0.85));
287	    ctx.fillStyle = mg;
288	    ctx.fillRect(0, h * 0.78, w, h * 0.22);
289	  }
