403	  private spawnSparks(scene: Scene, t0: number, t1: number, wall: number) {
404	    const cam = this.cam;
405	    for (const n of scene.nodes) {
406	      if (n.bellTime < 0 || n.bellTime <= t0 || n.bellTime > t1) continue;
407	      const k = n.pts.length - 2;
408	      const rng = createRng(`spark:${n.bellTime}`);
409	      const count = rng.int(3, 5);
410	      for (let i = 0; i < count && this.sparks.length < 120; i++) {
411	        this.sparks.push({
412	          x: n.pts[k] * cam.s + cam.x,
413	          y: n.pts[k + 1] * cam.s + cam.y,
414	          vx: rng.range(-9, 9),
415	          vy: rng.range(-16, -5),
416	          born: wall,
417	          life: rng.range(1.6, 2.6),
418	        });
419	      }
420	    }
421	  }
422	
423	  private drawSparks(wall: number) {
424	    if (!this.glowSprite || this.sparks.length === 0) return;
425	    const { ctx } = this;
426	    ctx.globalCompositeOperation = 'lighter';
427	    this.sparks = this.sparks.filter((s) => wall - s.born < s.life);
428	    for (const s of this.sparks) {
429	      const age = wall - s.born;
430	      const a = Math.sin(Math.PI * clamp01(age / s.life)) * 0.8;
431	      const x = s.x + s.vx * age;
432	      const y = s.y + s.vy * age;
433	      ctx.globalAlpha = a;
434	      ctx.drawImage(this.glowSprite, x - 6, y - 6, 12, 12);
435	    }
436	    ctx.globalAlpha = 1;
437	    ctx.globalCompositeOperation = 'source-over';
438	  }
439	
440	  private drawFireflies(wall: number) {
441	    if (!this.glowSprite) return;
442	    const { ctx, w, h } = this;
443	    ctx.globalCompositeOperation = 'lighter';
444	    for (const f of this.flies) {
445	      const T = this.reducedMotion ? 0 : wall;
446	      const x = (f.x + Math.sin(T * f.fx * Math.PI * 2 + f.p) * f.ax) * w;
447	      const y = (f.y + Math.cos(T * f.fy * Math.PI * 2 + f.p * 1.3) * f.ay) * h;
448	      const glow = this.reducedMotion ? 0.35 : Math.pow(0.5 + 0.5 * Math.sin(wall * f.f * Math.PI * 2 + f.p), 3);
449	      ctx.globalAlpha = 0.12 + 0.55 * glow;
450	      const s = 6 + f.r * 4;
451	      ctx.drawImage(this.glowSprite, x - s, y - s, s * 2, s * 2);
452	    }
453	    ctx.globalAlpha = 1;
454	    ctx.globalCompositeOperation = 'source-over';
455	  }
