457	  private drawVignette() {
458	    const { ctx, w, h } = this;
459	    const g = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.35, w / 2, h / 2, Math.max(w, h) * 0.8);
460	    g.addColorStop(0, 'rgba(5,8,16,0)');
461	    g.addColorStop(1, 'rgba(5,8,16,0.55)');
462	    ctx.fillStyle = g;
463	    ctx.fillRect(0, 0, w, h);
464	  }
